def seg_fig(a=(0, 0), b=(4, 1.2), h=260, desc=None):
    return gd({'A': a, 'B': b}, [('seg', 'A', 'B')], h=h, desc=desc or 'Segment AB on a blank page.')


def angle_fig(deg_pt=(2.2, 2.6), h=270, names=('P', 'Q', 'R')):
    a, v, c = names
    return gd({a: deg_pt, v: (0, 0), c: (3.4, 0)}, [('ray', v, a), ('ray', v, c), ('ang', v, c, a)], h=h,
              desc='Angle %s%s%s with vertex %s; ray %s%s is horizontal and ray %s%s rises to the upper right.' % (a, v, c, v, v, c, v, a))


def circle_fig(h=270, pt=True):
    P = {'O': (0, 0)}
    if pt:
        P['A'] = (2.2, 0)
    return gd(P, [('circle', 'O', 2.2)], h=h, lab={'O': 'sw'},
              desc='A circle with center O' + (' and a point A on the circle (to the right of O).' if pt else '.'))


